from pathlib import Path
import json,base64,re,subprocess
root=Path(__file__).resolve().parents[1]/'web/recipes/steamed-bass'
steps=[('clean',36,'清理鱼身，沿背部改刀','去鳞、鳃和内脏，剪去背鳍，刮净表面黏液并清洗。从鱼背沿骨划开较厚的背肉，两侧保持均匀；原片不建议在鱼身横切多道深口。','00:16–00:50'),('marinate',58,'姜葱水腌至少 20 分钟','姜、葱加水揉出汁，涂抹鱼身，并让背部开口接触姜葱水，腌至少 20 分钟。补充建议：用凉下来的姜葱水冷藏腌制。','00:51–01:00'),('shreds',68,'腌鱼时准备三丝','小葱、大葱、红椒切细丝，用冷水浸泡备用。原片说只用葱绿也可以。','01:01–01:11'),('rack',90,'擦干、抹油、架起鱼身','腌好后擦干鱼身，表面均匀抹少量花生油。用耐热筷子或蒸架将鱼架离盘底，鱼背铺姜丝；蒸制时不再铺葱。','01:12–01:35'),('steam',97,'按鱼重参考蒸制时间','蒸汽充足后入锅。作者参考：一斤鱼约 7 分钟，每增加 200 克加约 1 分钟。结合鱼身厚度和设备调整，确认鱼肉熟透。','01:36–01:41'),('finish',113,'倒汁、铺三丝、淋油豉油','鱼蒸好后倒掉盘中蒸汁，铺上沥干的三丝，淋热油激香，再沿鱼身周围淋蒸鱼豉油，即可上桌。','01:42–01:59')]
for name,t,*_ in steps:subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-y','-ss',str(t),'-i',str(root.parents[2]/'imports/6985bcb6000000000d00baa7.mp4'),'-vf','scale=480:-1','-frames:v','1',str(root/(name+'.jpg'))],check=True)
r={'id':'xhs-6985bcb6000000000d00baa7','title':'清蒸鲈鱼','servings':None,'source':'https://www.xiaohongshu.com/explore/6985bcb6000000000d00baa7','ingredients':[{'name':'鲈鱼','amount':1,'unit':'条（重量未注明）'}]+[{'name':n,'amount':None,'unit':'适量'} for n in ['姜','小葱','大葱','红椒','水','花生油','食用油（淋热油）','蒸鱼豉油']],'prep':[s[3] for s in steps[:3]],'cook':[s[3] for s in steps[3:]],'timing':{'prep':[{'min':8,'max':12},{'min':20,'max':20,'wait':True},{'min':4,'max':6}],'cook':[{'min':3,'max':5},{'min':7,'max':12,'wait':True},{'min':3,'max':5}]},'notes':['依据画面与烧录字幕提炼，未独立转写音频。','预计 45–60 分钟含至少 20 分钟腌制；按顺序保守估算，腌制时切三丝可缩短总时间。','视频未注明实际鱼重。作者时间参考以一斤（500 克）为基准，每增加 200 克加约 1 分钟；不是对所有鱼与设备的熟度保证。','原片使用温水揉姜葱；冷却后冷藏腌制为补充建议。','熟度补充判断：最厚处鱼肉不再半透明、容易分离，使用食品温度计可检查中心达到 63°C。','花生油用于蒸前抹鱼，后淋热油品种未注明，分开列出。'],'illustrated_steps':[{'title':s[2],'text':s[3],'source_time':s[4],'image':s[0]+'.jpg'} for s in steps]}
(root/'recipe.json').write_text(json.dumps(r,ensure_ascii=False,indent=2))
css=re.search(r'<style>(.*?)</style>',(root.parent/'pepper-ribs/index.html').read_text(),re.S)[1]+'.step:nth-child(4) img{object-position:50% 65%}'
def img(n):return 'data:image/jpeg;base64,'+base64.b64encode((root/(n+'.jpg')).read_bytes()).decode()
rows=''.join('<li>'+i['name']+'：'+(str(i['amount'])+' '+i['unit'] if i['amount'] else '适量')+'</li>' for i in r['ingredients'])
cards=''.join(f'<article class="step"><img src="{img(n)}" alt="{title}，原视频截图"><div><small>STEP {i:02} · 原片 {tm}</small><h2>{title}</h2><p>{txt}</p></div></article>' for i,(n,t,title,txt,tm) in enumerate(steps,1))
u='data:application/json;base64,'+base64.b64encode(json.dumps(r,ensure_ascii=False).encode()).decode()
s=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>清蒸鲈鱼 · 小厨房</title><style>{css}</style></head><body><main><div class="label">小厨房 / 视频提炼菜谱</div><h1>清蒸鲈鱼<small>预计 45–60 分钟 · 含腌制，保守估算</small></h1><p class="lead">背部改刀，姜葱去腥。架起蒸、倒掉汁，最后热油激香。</p><div class="info"><b>一次备齐 · 一项一行</b><ul class="prep-list">{rows}</ul><p class="note">原片未注明鱼重和人数；其余未标注用量显示“适量”。小葱、大葱、红椒是三丝配料，只用葱绿也可以。</p><b>蒸制时间怎么参考</b><p>作者给出的参考：500 克约 7 分钟，每增加 200 克加约 1 分钟。需结合鱼身厚度和蒸汽强度调整，不能仅凭计时判断熟度。</p><b>多菜同做</b><ol><li>炖菜先下锅，随后清理并腌鱼。</li><li>腌鱼的 20 分钟里切三丝、备其他菜，预计总用时可缩短。</li><li>临近上桌再蒸鱼；鱼蒸好立即倒汁、淋油和豉油。</li></ol><p class="note">冷却姜葱水后冷藏腌制为补充建议；蒸熟后最厚处鱼肉应不再半透明，食品温度计可检查中心达到 63°C。</p></div><div class="actions"><a href="{u}" download="清蒸鲈鱼.json">下载小厨房导入 JSON</a></div><section class="grid">{cards}</section><footer>来源：小红书「蔡成的菜」《蒸鱼万能公式，肉嫩不腥一次成功！春节必备》 · <a href="{r['source']}">原笔记</a><br>图片来自原片，文字依据画面与烧录字幕提炼，未独立转写音频。原片没有自制酱汁配比，使用现成蒸鱼豉油。预计时间按约 500 克鱼及一般家庭操作估算，较大的鱼可能超过该范围。</footer></main></body></html>'''
(root/'index.html').write_text(s)
print('Built steamed bass recipe')
